// Insert inserts the record into the database
func (t *IssuedReminderLine) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, IssuedReminderLineTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Reminder_no,
		t.Line_no,
		t.Attached_to_line_no,
		t.Type,
		t.Entry_no,
		t.Reminder_level,
		t.Posting_date,
		t.Document_date,
		t.Due_date,
		t.Document_type,
		t.Document_no,
		t.Description,
		t.Original_amount,
		t.Remaining_amount,
		t.No,
		t.Amount,
		t.Interest_rate,
		t.Gen_prod_posting_group,
		t.Tax_percent,
		t.Tax_calculation_type,
		t.Tax_amount,
		t.Tax_group_code,
		t.Tax_prod_posting_group,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (reminder_no, line_no, attached_to_line_no, type, entry_no, reminder_level, posting_date, document_date, due_date, document_type, document_no, description, original_amount, remaining_amount, no, amount, interest_rate, gen_prod_posting_group, tax_percent, tax_calculation_type, tax_amount, tax_group_code, tax_prod_posting_group) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (reminder_no, line_no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Issued_Reminder_Line: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(IssuedReminderLineTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *IssuedReminderLine) InsertAll(records []*IssuedReminderLine, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Reminder_no,
			r.Line_no,
			r.Attached_to_line_no,
			r.Type,
			r.Entry_no,
			r.Reminder_level,
			r.Posting_date,
			r.Document_date,
			r.Due_date,
			r.Document_type,
			r.Document_no,
			r.Description,
			r.Original_amount,
			r.Remaining_amount,
			r.No,
			r.Amount,
			r.Interest_rate,
			r.Gen_prod_posting_group,
			r.Tax_percent,
			r.Tax_calculation_type,
			r.Tax_amount,
			r.Tax_group_code,
			r.Tax_prod_posting_group,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, IssuedReminderLineTableName)
	columns := []string{"reminder_no", "line_no", "attached_to_line_no", "type", "entry_no", "reminder_level", "posting_date", "document_date", "due_date", "document_type", "document_no", "description", "original_amount", "remaining_amount", "no", "amount", "interest_rate", "gen_prod_posting_group", "tax_percent", "tax_calculation_type", "tax_amount", "tax_group_code", "tax_prod_posting_group"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

